mkdir -p /tmp/lamp21-probe && cat > /tmp/lamp21-probe/probe.mjs <<'EOF'
// Scratch probe: does a lamp written after the shell (runParts order) survive in the master bedroom?
import { Grid, runParts, B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
