g.fill([0, GROUND_Y, 0], [SITE_SIZE[0] - 1, GROUND_Y, SITE_SIZE[2] - 1], "grass_block");
runParts(g, [["shell", shell.build], ["probe", probe]], { palette: "/Volumes/ext1/swe/repos/mc-design-eval/benchmarks/plugin-baseline/runs/build-1/plantation/crew/lamp-21/palette.json", report: null });
console.log("refused:", JSON.stringify(g.refused ?? null));
console.log("at 57,11,43:", JSON.stringify(g.get ? g.get(57, 11, 43) : "n/a"));
EOF
cd /tmp/lamp21-probe && node probe.mjs 2>&1 | tail -20

